  String t(String key) {
    final langMap = _localizedValues[currentLanguage.code] ?? _localizedValues['en-US']!;
    return langMap[key] ?? _localizedValues['en-US']?[key] ?? _localizedValues['zh-CN']?[key] ?? key;
  }
  String tf(String key, Map<String, dynamic> params) {
    String res = t(key);
    params.forEach((k, v) {
      res = res.replaceAll('{}', v.toString());
    });
    return res;
  }

